attach(viewport: WindowViewport): void {
  viewport.on('keyboardHeightChange', (pixels: number) => {
    if (pixels > 0) {
      this.canFocus = true;
    } else {
      this.canFocus = false;
    }
  });
}

export class FocusBinding {
  private canFocus: boolean = false;
  attach(viewport: WindowViewport): void {
    viewport.on('keyboardHeightChange', (pixels: number) => {
      if (pixels > 0) {
        this.canFocus = true;
      } else {
        this.canFocus = false;
      }
    });
  }
}

@Component
export struct FocusPreference {
  @State canFocus: boolean = false;
  build() {
    Button('Enable focus').onClick(() => {
      this.canFocus = true;
    });
  }
}

export class FocusBinding {
